using Astrea.BattleActions;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GainSomethingWithDrawBackOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/GainSomethingWithDrawBackOmenData")]
public class GainSomethingWithDrawBackOmenData : OnStartOfBattleOmenData
{
	[Header("Good Effect")]
	[SerializeField]
	private BattleAction goodEffectAction;

	[SerializeField]
	private int goodEffectValue;

	[SerializeField]
	private OmenLogic goodEffectOmenLogic;

	[Header("Bad Effect")]
	[SerializeField]
	private BattleAction badEffectAction;

	[SerializeField]
	private int badEffectValue;

	[SerializeField]
	private OmenLogic badEffectLogic;

	[Header("On Overcorrupt Omen Data")]
	[SerializeField]
	private bool enableOnOvercorruptOmenData;

	[SerializeField]
	[ShowIf("enableOnOvercorruptOmenData")]
	private OnEnemyOverCorruptedOmenData onEnemyOverCorruptedOmenData;

	public BattleAction GoodEffectAction => goodEffectAction;

	public BattleAction BadEffectAction => badEffectAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				goodEffectOmenLogic.ActivateOmen(goodEffectAction, goodEffectValue, null, null);
				badEffectLogic.ActivateOmen(badEffectAction, badEffectValue, null, null);
			});
		};
		AddToStartOfBattleOmenActions();
		if (enableOnOvercorruptOmenData)
		{
			onEnemyOverCorruptedOmenData.Initialize(omenInstance);
		}
	}

	public override void OmenRemoved()
	{
		if (enableOnOvercorruptOmenData)
		{
			onEnemyOverCorruptedOmenData.OmenRemoved();
		}
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		string localizedGainWithDrawBack = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedGainWithDrawBack();
		string arg = goodEffectAction.GetActionDescription(goodEffectValue).RemoveLast().LowercaseFirst();
		string arg2 = badEffectAction.GetActionDescription(badEffectValue).LowercaseFirst();
		return GetStartOfBattleLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + string.Format(localizedGainWithDrawBack, arg, arg2) + (enableOnOvercorruptOmenData ? ("\n" + onEnemyOverCorruptedOmenData.OmenConvertedDescription()) : "");
	}
}
